			}
			else if (_largeParserLetGo != null && _largeParserLetGo.TryGetTarget(out var letGo))
			{
				spare = letGo;
				_largeParserLetGo.SetTarget(null!);
			}
			else if (_spareParserLetGo != null && _spareParserLetGo.TryGetTarget(out var letGoSpare))
			{
				spare = letGoSpare;
				_spareParserLetGo.SetTarget(null!);
			}
			else
				return new Parser();
			return spare;
		}

		static void Recycle(Parser parser)
		{
			if (parser.Entries.Capacity > KeptEntries)
			{
				if (_largeParser != null && !ReferenceEquals(_largeParser, parser))
					(_largeParserLetGo ??= new global::System.WeakReference<Parser>(_largeParser)).SetTarget(_largeParser);

				// The same question the ordinary slot asks below: is the room far larger than the
				// use. The bound decides which slot holds the arena, not whether to keep it.
				if (parser.Entries.Capacity <= 4 * parser.Entries.Count)
					_largeParserIdle = 0;
				else if (++_largeParserIdle >= LargeParserIdle)
				{
					(_largeParserLetGo ??= new global::System.WeakReference<Parser>(parser)).SetTarget(parser);
					_largeParser = null;
					_largeParserIdle = 0;

					return;
				}

				_largeParser = parser;

				return;
			}

			// The ordinary slot lets go by the rule the parked one uses. Room and use are the
			// list's own two numbers, which is as commensurable as it gets; four times and not
			// twice because a list grows by doubling, so one doubling is ordinary slack.
			if (parser.Entries.Capacity <= 4 * parser.Entries.Count)
				_spareParserIdle = 0;
			else if (++_spareParserIdle >= SpareParserIdle)
			{
				(_spareParserLetGo ??= new global::System.WeakReference<Parser>(parser)).SetTarget(parser);
				_spareParserIdle = 0;

				return;
			}

			if (_spareParser == null)
				_spareParser = parser;
			else if (_deeperParserCount < 3)
				(_deeperParsers ??= new Parser?[3])[_deeperParserCount++] = parser;
		}

		/// <summary>
		/// One line per step of the automaton, on standard error, when the build defines
		/// <c>DOTGRAM_TRACE</c> — nothing else to configure, and when it does not, the
		/// calls are removed at their sites, arguments and all.
		/// </summary>
		[global::System.Diagnostics.Conditional("DOTGRAM_TRACE")]
		static void Trace(string action, int state, int position, int arena)
		{
			global::System.Console.Error.WriteLine(
				".Gram " + action + " state=" + state.ToString() +
				" at " + position.ToString() + " arena=" + arena.ToString());
		}

		/// <summary>
		/// The same line with the rule it happened in and a window of the input around
		/// the position, the caret marking the position itself.
		/// </summary>
		[global::System.Diagnostics.Conditional("DOTGRAM_TRACE")]
		static void Trace(
			string action, int state, int position, int arena,
			global::System.ReadOnlySpan<char> text, string rule)
		{
			var from   = position > 16 ? position - 16 : 0;
			var to     = position + 16 < text.Length ? position + 16 : text.Length;
			var window =
				(from < position && position <= text.Length ? text.Slice(from, position - from).ToString() : "") +
				"^" +
				(position >= 0 && position < to ? text.Slice(position, to - position).ToString() : "");

			window = window
				.Replace("\r", "\\r")
				.Replace("\n", "\\n")
				.Replace("\t", "\\t");

			global::System.Console.Error.WriteLine(
				".Gram " + action + (rule.Length > 0 ? " in " + rule : "") +
				" state=" + state.ToString() + " at " + position.ToString() +
				" \"" + window + "\" arena=" + arena.ToString());
		}
	}
}
